with seed(standard_code,code,name,seq,required,classification,grade_code) as (values
('พ 1.1','HPE-P6-01','อธิบายความสำคัญของระบบสืบพันธุ์ ระบบไหลเวียนโลหิต และระบบหายใจ ที่มีผลต่อสุขภาพ การเจริญเติบโต และพัฒนาการ',1,false,'should_know','P6'),
('พ 1.1','HPE-P6-02','อธิบายวิธีการดูแลรักษาระบบสืบพันธุ์ ระบบไหลเวียนโลหิต และระบบหายใจ ให้ทำงานตามปกติ',2,true,'must_know','P6'),
('พ 2.1','HPE-P6-03','อธิบายความสำคัญของการสร้างและรักษาสัมพันธภาพกับผู้อื่น',3,false,'should_know','P6'),
('พ 2.1','HPE-P6-04','วิเคราะห์พฤติกรรมเสี่ยงที่อาจนำไปสู่การมีเพศสัมพันธ์ การติดเชื้อเอดส์ และการตั้งครรภ์ก่อนวัยอันควร',4,true,'must_know','P6'),
('พ 3.1','HPE-P6-05','แสดงทักษะการเคลื่อนไหวร่วมกับผู้อื่นในลักษณะแบบผลัด และแบบผสมผสานได้ตามลำดับทั้งแบบอยู่กับที่ เคลื่อนที่ และใช้อุปกรณ์ประกอบและการเคลื่อนไหวประกอบเพลง',5,false,'should_know','P6'),
('พ 3.1','HPE-P6-06','จำแนกหลักการเคลื่อนไหวในเรื่องการรับแรง การใช้แรง และความสมดุลในการเคลื่อนไหวร่างกายในเกม เล่นกีฬา และนำผลมาปรับปรุง เพิ่มพูนวิธีปฏิบัติของตนและผู้อื่น',6,false,'should_know','P6'),
('พ 3.1','HPE-P6-07','เล่นกีฬาไทย กีฬา สากลประเภทบุคคลและประเภททีมอย่างละ ๑ ชนิด',7,true,'must_know','P6'),
('พ 3.1','HPE-P6-08','ใช้ทักษะกลไกเพื่อปรับปรุงเพิ่มพูนความสามารถของตนและผู้อื่นในการเล่นกีฬา',8,false,'should_know','P6'),
('พ 3.1','HPE-P6-09','ร่วมกิจกรรมนันทนาการ อย่างน้อย ๑ กิจกรรม แล้วนำความรู้และหลักการที่ได้ไปใช้เป็นฐานการศึกษาหาความรู้เรื่องอื่น ๆ',9,false,'should_know','P6'),
('พ 3.2','HPE-P6-10','อธิบายประโยชน์และหลักการออกกำลังกายเพื่อสุขภาพ สมรรถภาพทางกายและการสร้างเสริมบุคลิกภาพ',10,true,'must_know','P6'),
('พ 3.2','HPE-P6-11','เล่นเกมที่ใช้ทักษะการวางแผนและสามารถเพิ่มพูนทักษะการออกกำลังกายและเคลื่อนไหวอย่างเป็นระบบ',11,false,'should_know','P6'),
('พ 3.2','HPE-P6-12','เล่นกีฬาที่ตนเองชื่นชอบและสามารถประเมินทักษะการเล่นของตนเป็นประจำ',12,false,'should_know','P6'),
('พ 3.2','HPE-P6-13','ปฏิบัติตามกฎ กติกาตามชนิดกีฬาที่เล่น โดยคำนึงถึงความปลอดภัยของตนเองและผู้อื่น',13,false,'should_know','P6'),
('พ 3.2','HPE-P6-14','จำแนกกลวิธีการรุก การป้องกันและนำไปใช้ในการเล่นกีฬา',14,false,'should_know','P6'),
('พ 3.2','HPE-P6-15','เล่นเกมและกีฬาด้วยความสามัคคีและมีน้ำใจนักกีฬา',15,false,'should_know','P6'),
('พ 4.1','HPE-P6-16','แสดงพฤติกรรมในการป้องกันและแก้ไขปัญหาสิ่งแวดล้อมที่มีผลต่อสุขภาพ',16,false,'should_know','P6'),
('พ 4.1','HPE-P6-17','วิเคราะห์ผลกระทบที่เกิดจากการระบาดของโรคและเสนอแนวทางการป้องกันโรคติดต่อสำคัญที่พบในประเทศไทย',17,true,'must_know','P6'),
('พ 4.1','HPE-P6-18','แสดงพฤติกรรมที่บ่งบอกถึงความรับผิดชอบต่อสุขภาพของส่วนรวม',18,false,'should_know','P6'),
('พ 4.1','HPE-P6-19','สร้างเสริมและปรับปรุงสมรรถภาพทางกายเพื่อสุขภาพอย่างต่อเนื่อง',19,false,'should_know','P6'),
('พ 4.1','HPE-P6-20','วิเคราะห์ผลกระทบจากความรุนแรงของภัยธรรมชาติที่มีต่อร่างกาย จิตใจ และสังคม',20,false,'should_know','P6'),
('พ 4.1','HPE-P6-21','ระบุวิธีปฏิบัติตน เพื่อความปลอดภัยจากธรรมชาติ',21,false,'should_know','P6'),
('พ 5.1','HPE-P6-22','วิเคราะห์สาเหตุของการติดสารเสพติดและชักชวนให้ผู้อื่นหลีกเลี่ยงสารเสพติด',22,true,'must_know','P6')
)
insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status)
select t.id,s.code,s.name,null,s.seq,'active' from seed s join public.learning_subjects sub on sub.code='HEALTH-PE' join public.learning_skills sk on sk.subject_id=sub.id and sk.code='HEALTH-PE' join public.learning_topics t on t.skill_id=sk.id and t.code=s.standard_code
on conflict(topic_id,code) do update set name=excluded.name,sequence_no=excluded.sequence_no,updated_at=now();
